import java.util.Scanner;

public class Main {
    static final int N = 100, D = 31, MOD = 1000000007;
    static int d, cur;
    static int[] a = new int[N];
    static long n;
    static Matrix[] bas = new Matrix[N];

    static class Matrix {
        long[][] f = new long[D + 1][D + 1];

        Matrix() {
            for (int i = 0; i <= d; i++) {
                for (int j = 0; j <= d; j++) {
                    f[i][j] = 0;
                }
            }
        }

        Matrix multiply(Matrix oth) {
            Matrix ans = new Matrix();
            for (int i = 0; i <= d; i++) {
                for (int j = 0; j <= d; j++) {
                    for (int k = 0; k <= d; k++) {
                        ans.f[i][j] = (ans.f[i][j] + this.f[i][k] * oth.f[k][j]) % MOD;
                    }
                }
            }
            return ans;
        }
    }

    static Matrix rotate(int u) {
        u = (u + d) % d;
        Matrix ans = new Matrix();
        for (int i = 0; i < d; i++) {
            ans.f[i][(i + u) % d] = 1;
        }
        ans.f[d][d] = 1;
        return ans;
    }

    static void init() {
        bas[0] = new Matrix();
        for (int i = 1; i < d; i++) {
            bas[0].f[i][i] = 1;
        }
        bas[0].f[d][0] = 1;
        bas[0].f[d][d] = 2;
        bas[0].f[0][d] = -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        d = sc.nextInt();

        long tempN = n;
        cur = 0;
        while (tempN > 0) {
            a[cur] = (int)(tempN % d);
            tempN /= d;
            cur++;
        }

        init();

        for (int i = 1; i < cur; i++) {
            bas[i] = rotate(0);
            for (int j = 0; j < d; j++) {
                bas[i] = bas[i].multiply(bas[i - 1]).multiply(rotate(1));
            }
        }

        Matrix ans = rotate(0);
        for (int i = cur - 1; i >= 0; i--) {
            for (int j = 0; j < a[i]; j++) {
                ans = ans.multiply(bas[i]).multiply(rotate(1));
            }
        }

        System.out.println((ans.f[d][d] + MOD) % MOD);
        sc.close();
    }
}
